<?php
require_once __DIR__.'/../includes/admin.php';require_role(['super_admin','admin','editor']);$pdo=db();
if(is_post()){verify_csrf();$a=$_POST['action']??'';try{if($a==='save'){$id=(int)($_POST['id']??0);$d=[trim($_POST['title_en']??''),trim($_POST['title_am']??''),trim($_POST['description_en']??''),trim($_POST['description_am']??''),trim($_POST['speaker']??''),trim($_POST['bible_reference']??''),trim($_POST['video_url']??''),trim($_POST['audio_url']??''),($_POST['status']??'draft')==='published'?'published':'draft'];if($id){$st=$pdo->prepare('UPDATE sermons SET title_en=?,title_am=?,description_en=?,description_am=?,speaker=?,bible_reference=?,video_url=?,audio_url=?,status=? WHERE id=?');$st->execute([...$d,$id]);}else{$st=$pdo->prepare('INSERT INTO sermons(title_en,title_am,description_en,description_am,speaker,bible_reference,video_url,audio_url,status) VALUES(?,?,?,?,?,?,?,?,?)');$st->execute($d);}log_admin($id?"Updated sermon #$id":'Created sermon');flash('admin_success','Sermon saved.');}if($a==='delete'){$id=(int)$_POST['id'];$pdo->prepare('DELETE FROM sermons WHERE id=?')->execute([$id]);log_admin("Deleted sermon #$id");flash('admin_success','Sermon deleted.');}}catch(Throwable $e){flash('admin_error','Sermon error: '.$e->getMessage());}redirect('admin/sermons.php');}
$edit=null;if(isset($_GET['edit'])){$st=$pdo->prepare('SELECT * FROM sermons WHERE id=?');$st->execute([(int)$_GET['edit']]);$edit=$st->fetch();}$rows=$pdo->query('SELECT * FROM sermons ORDER BY created_at DESC')->fetchAll();admin_page('Sermons','sermons','Manage sermons, speakers, video links and audio links.');admin_flash();
?><div class="admin-panel"><h2><?= $edit?'Edit Sermon':'Add Sermon' ?></h2><form class="admin-form" method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e((string)($edit['id']??0))?>"><div class="admin-form-grid"><label>Title (English)<input name="title_en" required value="<?=e($edit['title_en']??'')?>"></label><label>Title (Amharic)<input name="title_am" value="<?=e($edit['title_am']??'')?>"></label></div><div class="admin-form-grid"><label>Description (English)<textarea name="description_en" rows="4"><?=e($edit['description_en']??'')?></textarea></label><label>Description (Amharic)<textarea name="description_am" rows="4"><?=e($edit['description_am']??'')?></textarea></label></div><div class="admin-form-grid three"><label>Speaker<input name="speaker" value="<?=e($edit['speaker']??'')?>"></label><label>Bible Reference<input name="bible_reference" value="<?=e($edit['bible_reference']??'')?>"></label><label>Status<select name="status"><option value="draft" <?=($edit['status']??'')==='draft'?'selected':''?>>Draft</option><option value="published" <?=($edit['status']??'')==='published'?'selected':''?>>Published</option></select></label></div><label>Video URL (YouTube or direct)<input name="video_url" placeholder="https://www.youtube.com/watch?v=..." value="<?=e($edit['video_url']??'')?>"></label><label>Audio URL<input name="audio_url" value="<?=e($edit['audio_url']??'')?>"></label><div class="admin-actions"><button class="btn primary">Save Sermon</button><?php if($edit):?><a class="btn outline" href="sermons.php">Cancel</a><?php endif;?></div></form></div><div class="admin-panel"><h2>Sermon Library</h2><div class="admin-table-wrap"><table class="admin-table"><tr><th>Title</th><th>Speaker</th><th>Video</th><th>Status</th><th>Actions</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['title_en'])?></td><td><?=e($r['speaker'])?></td><td><?=!empty($r['video_url'])?'✓':'—'?></td><td><span class="status <?=e($r['status'])?>"><?=e($r['status'])?></span></td><td><a class="btn small outline" href="sermons.php?edit=<?=$r['id']?>">Edit</a> <form style="display:inline" method="post" onsubmit="return confirm('Delete sermon?')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn small" style="background:var(--red);color:#fff">Delete</button></form></td></tr><?php endforeach;?></table></div></div><?php admin_end(); ?>
